  ],
})
export class AppModule {}

const TYPES = { Repo: Symbol.for('OrderRepository') } as const;

@injectable()
class OrderService {
  constructor(@inject(TYPES.Repo) private repo: OrderRepository) {}
}

container.bind<OrderRepository>(TYPES.Repo).to(SqlOrderRepository).inSingletonScope();
container.bind(OrderService).toSelf();

export function createOrderService(deps: {
  repo: OrderRepository;
  clock: Clock;
}): OrderService {
  return { get: (id) => deps.repo.find(id, deps.clock.now()) };
}

